      var c = St().findCourse(s.term, s.course);
      if (!c) { var ot = s.term === FALL ? SPRING : FALL, inOther = St().findCourse(ot, s.course); out.block.push('You aren’t registered for **' + s.course + '** in ' + TA.SOC.label(s.term) + '.' + (inOther ? ' You’re taking it in **' + TA.SOC.label(ot) + '** — want to drop it there?' : '')); if (inOther) out.offers = [{ label: 'Drop ' + s.course + ' in ' + TA.SOC.label(ot), value: 'drop ' + s.course + (ot === FALL ? ' this semester' : ' in spring') }]; return out; }
      if (s.term === FALL && after(cal.lastWithdraw)) out.block.push('The last day to withdraw from a Fall 2026 course was ' + fdate(cal.lastWithdraw) + '.');
      var left = St().termUnits(s.term) - c.units;
