    fill: function (name, n, s) { if (name === 'amount' && n.money.length) { s.amount = n.money[0]; return true; } if (name === 'amount') { var m = /^\s*(\d{1,4})(\.\d{1,2})?\s*$/.exec(n.t); if (m) { s.amount = +n.t; return true; } } return false; },
    check: function (s) { var out = { block: [], warn: [] }; if (!(s.amount > 0)) out.block.push('Enter an amount greater than $0.'); if (s.amount > 1000) out.block.push('This prototype caps a single deposit at $1,000.'); if (D().uscard.status === 'frozen') out.warn.push('Your card is frozen, so funds can’t be spent until it’s reactivated or replaced.'); return out; },
