      var symF = /\b(sore throat|fever|cough|cold|flu|rash|headache|migraine|cramps|stomach ?ache|ear ?ache|uti|infection|sprain\w*|injur\w*|pain|allerg\w*|congestion|sinus)\b/.exec(n.t);
