    'sign-up-trojansalert': function (o) { o.block.push('There’s nothing to sign up for: **students are enrolled in TrojansAlert automatically**, so you’ll get emergency texts and emails at the contact info USC has for you. (The annual Nixle sign-up is for parents, community members and alumni.)'); },
    'apply-for-graduation-degree-check': function (o) { var pr = D().profile; if (/undergrad/i.test(pr.level || '') && !/(fall 2026|spring 2027|summer 2027)/i.test(pr.gradTerm || '')) o.block.push('Your expected graduation term on file is **' + (pr.gradTerm || 'not set') + '**, so there’s nothing to submit yet. USC Viterbi says undergraduates don’t apply to graduate: finish every requirement on your **STARS report** and keep your expected graduation term current (Experience USC → My Profile → Academics → My Degree).'); },
    'waive-student-health-insurance': function (o) { if (/waived/i.test(D().health.insurance || '')) o.block.push('Your account already shows the SHIP charge **waived for 2026–27**, so there’s nothing to submit this year. The waiver is annual: the next one is due by the third week of fall classes (**Fall 2027: September 10, 2027**).'); },
    'enroll-in-student-health-insurance': function (o) { if (/waived/i.test(D().health.insurance || '')) { o.block.push('Your account shows SHIP **waived for 2026–27**. USC’s pages don’t describe re-enrolling after a waiver mid-year, so I can’t submit this — contact the Student Health Insurance Office at **(213) 821-1550** (or studenthealth@usc.edu), and they can tell you whether you can enroll now.'); o.offers.push({ label: 'Student Health insurance contacts', value: 'how do i contact the student health insurance office' }); } },
