    'request-late-fee-reversal-delayed-aid': function (o) { if (!D().billing.items.some(function (x) { return /late fee|finance charge/i.test(x.desc); })) { o.block.push('Your account doesn’t show any late fees or finance charges, so there’s nothing to reverse. (If aid arrives late and you’re charged, pay the balance minus those charges, then ask Financial Aid through askUSC to reverse them.)'); } },
