      if (/\bfinal (grades?|marks?|projects?|papers?|essays?|presentations?|drafts?|version|transcript|semester|year|deadline|day of|answer|decision|step|exam grade)\b/.test(t) && !/\b(finals|final exams? (date|time|schedule|day|room|when))\b/.test(t)) return null;
      if (/\b(osas|testing center|accommodat\w*|extended time|extra time|additional time|time and a half)\b/.test(t)) return null;
      if (/\b(move|moving|check|checking) out\b|\bvacate\b|\b(fly|flight|go|going|travel\w*|leave|leaving) home\b|\b(book|buy) (a |my )?(flight|ticket)\b/.test(t) && !/\bwhen (is|are) my (last )?finals?\b/.test(t)) return null;
      var explicitTerm = /\b(spring|2027|fall|2026)\b/.test(t);
      var term = /\bspring|2027\b/.test(t) ? '20271' : '20263', label = TA.SOC.label(term);
      if (!explicitTerm && D().signedIn && n.courses.length && n.courses.every(function (c) { return !St().findCourse('20263', c) && St().findCourse('20271', c); })) { term = '20271'; label = TA.SOC.label(term); }
      var mineQ = /\b(my|i have|do i have|i finish|am i done|i'?m done|do i finish)\b/.test(t);
      if (mineQ && D().signedIn && !n.courses.length && /\b(conflict\w*|overlap\w*|same (day|time)|back[- ]to[- ]back|three finals|3 finals|two finals|2 finals)\b|\b(last|final) (final|exam)\b|\bwhen (do|will) i (finish|be done)\b|\bam i done\b|\bwhen is my last\b/.test(t)) {
        var Fx = TA.FINALS[term], rows = [];
        St().termCourses(term).forEach(function (c) {
          var lec = c.sections.find(function (x) { return /lecture/i.test(x[1]); }) || c.sections[0];
          var r = TA.SOC.finalFor(term, c.code, lec[2], lec[3], lec[4]);
          if (r && r.day) {
            var dm = /([A-Za-z]+) (\d{1,2})\s*$/.exec(r.day), MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december'];
            var mi = dm ? MONTHS.indexOf(dm[1].toLowerCase()) : -1, hm = /^(\d{1,2})(?::(\d{2}))?/.exec(r.hour || ''), hh = hm ? +hm[1] : 0;
            if (/^\d/.test(r.hour || '') && hh < 8 && !/AM\s*[–-]/.test(r.hour)) hh += 12; // "2:00 – 4:00 PM" starts in the afternoon
            if (/^\d{1,2}(:\d{2})?\s*PM/.test(r.hour || '') && hh < 12) hh += 12;
            var yr = term === '20271' ? 2027 : 2026;
            rows.push({ code: c.code, day: r.day, hour: r.hour, at: mi >= 0 ? new Date(yr, mi, +dm[2], hh, hm && hm[2] ? +hm[2] : 0) : null });
          }
        });
        if (rows.length) {
          var byDay = {}; rows.forEach(function (r) { (byDay[r.day] = byDay[r.day] || []).push(r); });
          var clash = [], three = [];
          Object.keys(byDay).forEach(function (d) { var L = byDay[d]; if (L.length >= 3) three.push(d); L.forEach(function (a, i) { L.slice(i + 1).forEach(function (b) { if (a.hour === b.hour) clash.push(a.code + ' and ' + b.code + ' (' + d + ', ' + a.hour + ')'); }); }); });
          var order = rows.slice().sort(function (a, b) { return (a.at && b.at) ? a.at - b.at : 0; });
          var last = order[order.length - 1];
          var list = order.map(function (r) { return '- **' + r.code + '**: ' + r.day + ', ' + r.hour; }).join('\n');
          var lead = /\b(conflict\w*|overlap\w*|same (day|time)|back[- ]to[- ]back|three finals|3 finals|two finals|2 finals)\b/.test(t)
            ? (clash.length ? 'Yes: ' + clash.join('; ') + ' are scheduled at the same time. Check with Academic Counseling Services about resolving the conflict, as the Registrar’s schedule advises.' : three.length ? 'None of your finals are at the same time, but you have three on ' + three.join(', ') + '.' : 'No. None of your **' + label + '** finals are at the same time' + (Object.keys(byDay).length === rows.length ? ', and each is on a different day.' : '.'))
            : 'Your last **' + label + '** final is **' + last.code + '** on **' + last.day + '**, ' + last.hour + '.';
          return bot(lead + '\n\nYour ' + label + ' finals' + (Fx && Fx.dates ? ' (exam period ' + Fx.dates + ')' : '') + ':\n' + list + '\n\nThese come from the Registrar’s Final Exam Schedule for your lecture times. Your instructor confirms the room.', { sources: [{ url: 'https://arr.usc.edu/final-exam-schedule/', title: 'Final Exam Schedule – Office of Academic Records and Registrar' }], kind: 'c' });
        }
      }
