      var src = [{ url: 'https://arr.usc.edu/final-exam-schedule/', title: 'Final Exam Schedule – Office of Academic Records and Registrar' }];
      var fmt = function (r) { return r.day ? '**' + r.day + '**, ' + r.hour : r.hour; };
