      var md = 'Here’s how your courses line up with the GE Program’s current course lists:\n\n'
        + (doneL.length ? '**Completed**\n' + doneL.map(function (x) { return '- ' + x; }).join('\n') + '\n\n' : '')
        + (progL.length ? '**In progress (Fall 2026)**\n' + progL.map(function (x) { return '- ' + x; }).join('\n') + '\n\n' : '')
