      var chk = a.check(p.slots) || { block: [], warn: [] };
      if (chk.block && chk.block.length) {
        B.pending = null; B.ctx.lastBlocked = { aid: a.id, turn: B.ctx.turn || 0, raw: B.ctx.lastUserQ || '' };
        var md = chk.block.length === 1 ? chk.block[0] : 'I can’t do that yet:\n' + chk.block.map(function (b) { return '- ' + b; }).join('\n');
        return [bot(md, { chips: (chk.offers || []).map(function (o) { return chip(o.label, o.value, 'action'); }).concat([chip('How does this work at USC?', 'how do i ' + a.title.toLowerCase())]).slice(0, 4) })];
      }
