      // a reschedule shows the booking it replaces before you confirm
      var mvr = B.r4MoveRow(p.slots); if (mvr) { pv.rows = (pv.rows || []).concat([mvr]); pv.title = String(pv.title).replace(/^Reserve (.*)$/, 'Move $1 reservation').replace(/^Book (.*)$/, 'Move $1'); }
      p.stage = 'confirm';
      var card = { type: 'confirm', id: TA.uid(), title: pv.title, icon: a.icon, rows: pv.rows, warn: chk.warn || [], notes: (pv.notes || []).filter(Boolean), steps: pv.steps || [], fine: pv.fine || [], sources: pv.sources || [], system: a.system, status: 'pending', danger: !!pv.danger };
      p.cardId = card.id;
