      if (/ (but|wait|hold|first|before|not|no|nope|dont|don|cancel|change|instead|actually|except|unless|if|what|how|when|why|can|could|would|will|should|does|did|stop|later|maybe) /.test(x)) return false;
      if (!/ (yes|yeah|yea|ya|yep|yup|sure|ok|okay|okie|kk|confirm|confirmed|correct|right|go ahead|do it|go for it|proceed|looks good|sounds good|alright|all right|absolutely|definitely|perfect|si|sí|claro|affirmative|lgtm|please do|of course) /.test(x)) return false;
      var PH = ['yes please', 'yes sir', 'sure thing', 'i confirm', 'do it', 'go ahead', 'go for it', 'send it', 'book it', 'pay it', 'sounds good', 'sounds great', 'sounds right', 'looks good', 'looks right', 'looks great', 'looks correct', 'looks fine', 'all good', 'thats right', 'thats correct', 'that is right', 'that is correct', 'thats good', 'thats fine', 'thats perfect', 'this is right', 'this is correct', 'its correct', 'its right', 'all right', 'of course', 'please do', 'por favor', 'thank you', 'thanks', 'yes', 'yeah', 'yea', 'ya', 'yep', 'yup', 'sure', 'ok', 'okay', 'okie', 'kk', 'k', 'confirm', 'confirmed', 'proceed', 'submit', 'correct', 'right', 'exactly', 'perfect', 'great', 'awesome', 'alright', 'absolutely', 'definitely', 'please', 'si', 'sí', 'claro', 'affirmative', 'ty', 'lgtm', 'cool', 'fine', 'good', 'nice', 'go', 'lets', 'just', 'so', 'and', 'then', 'well', 'oh', 'um', 'uh', 'hey', 'very', 'much', 'it', 'that', 'is'];
      var prev;
      do { prev = x; PH.forEach(function (w) { x = x.split(' ' + w + ' ').join(' '); }); } while (x !== prev);
