      var refers = /\b(it|that|this|they|them|those|the (appointment|appt|booking|session|payment|rest|remainder|remaining|balance|class|course|plan|meal plan|books?|items?|request|card|order|transcript|deposit|reservation|room|change)|my (appointment|appt|booking|session|payment|class|plan|books?|request|order|transcript|reservation))\b/.test(t) || t.split(' ').length <= 5;
      var wh = /^(when|what time|what day|where|how long|when will|when does|when do|when is|when are|is it|did it|has it|will it|what'?s the deadline|what is the deadline|when'?s)\b/.test(t);
      // "cancel that", "undo that", "take it back"
