      if (/^(book_advising|book_health|book_career|book_writing|book_tutoring|reserve_room)$/.test(ld.aid) && apptQ) return [bot('Your **' + String(ld.title || a.title).replace(/ (booked|reserved|moved)$/i, '').toLowerCase() + '**: ' + rows.filter(function (x) { return /^(when|format|where|with|room|library|type)$/i.test(x[0]); }).map(function (x) { return '**' + x[0] + ':** ' + x[1]; }).join(' · ') + '.', { chips: [chip('Show my appointments', 'show my appointments')] })];
      if (ld.aid === 'pay_balance' && /\b(rest|remaining|remainder|balance|what'?s left|left to pay|other half|still owe)\b/.test(t)) return [bot('Your remaining balance is **' + TA.money(D().billing.balance) + '**' + (D().billing.balance > 0 ? ', due **' + TA.fmtDate(D().billing.due) + '**.' : ' — you’re paid up.'), { chips: [chip('Show my bill', 'show my bill')] })];
