    for (var k in input) { if (!sch.properties[k]) return 'unexpected field ' + k; var p = sch.properties[k]; if (p.enum && p.enum.indexOf(input[k]) < 0) return k + ' must be one of ' + p.enum.join(', '); if (p.type === 'string' && typeof input[k] !== 'string') return k + ' must be a string'; }
