      var R = (res.results || []).filter(function (r) { return r.cov >= 0.3; }).slice(0, 8);
      R.forEach(function (r) { turnSources.push({ url: r.url, title: r.t === 'f' ? r.ti + ' – askUSC' : (r.utitle || r.ti) }); });
