        return found.length ? JSON.stringify(found.map(function (c) { return { code: c.code, title: c.title, units: c.units, countsTowardGE: !!c.ge, prerequisites: c.prereq, sections: c.sections.slice(0, 12).map(function (s) { return { id: s.id + (s.d ? 'D' : 'R'), type: s.type, meets: s.meets, instructor: s.instr, seatsOpen: Math.max(0, s.seats - s.reg), seats: s.seats, cancelled: s.cancelled }; }) }; })) + '\n(A course card with these sections is shown to the student.)' : 'No courses found in the ' + input.term + ' Schedule of Classes.';
