/* ===== main.js : boot ===== */
(function () {
  'use strict';
  var TA = window.TA = window.TA || {};
  TA.settings = Object.assign({ ai: false, model: 'claude-opus-5-5', rememberKey: false, realDate: false }, TA.store.get('settings', {}) || {});
  TA.saveSettings = function () { TA.store.set('settings', TA.settings); };
  var handlers = {};
  TA.on = function (e, f) { (handlers[e] = handlers[e] || []).push(f); };
  TA.emit = function (e, d) { (handlers[e] || []).forEach(function (f) { try { f(d); } catch (x) { console.error(x); } }); };

  function text(id) { var el = document.getElementById(id); if (el) return el.textContent.trim(); var b = window.TA_BLOBS && window.TA_BLOBS[id]; return b ? String(b).trim() : ''; }

  function boot(opts) {
    opts = opts || {};
    try { TA.KB_META = JSON.parse(text('ta-meta') || '{}'); } catch (e) { TA.KB_META = {}; }
    TA.FINALS = TA.KB_META.finals || null;
    TA.GE_LISTS = TA.KB_META.geLists || null;
    TA.State.load();
    TA.Brain.restore();
    // course catalog (small) first so course codes parse right away
    var socB64 = text('ta-soc');
    if (socB64) TA.gunzipB64(socB64).then(function (t) { TA.SOC.load(JSON.parse(t)); TA.emit('soc-ready'); }).catch(function (e) { console.error('SOC load failed', e); });
    try { TA.Process.load(JSON.parse(text('ta-acts') || '[]')); } catch (e) { console.error('process actions failed to load', e); }
    var kbB64 = text('ta-kb');
    if (kbB64) { TA.Search.init(kbB64); if (window.TA_BLOBS) delete window.TA_BLOBS['ta-kb']; } else if (!opts.kbLater) { TA.Search.failed = 'Knowledge base missing'; }
    TA.UI.init();
    TA.Host.init();
    TA.UI.renderMode();
    var status = document.getElementById('ta-status');
    TA.on('kb-ready', function (st) {
      document.documentElement.setAttribute('data-kb', 'ready');
      var n = document.getElementById('kb-count'); if (n && st) n.textContent = st.docs.toLocaleString();
      document.querySelectorAll('.ta-loading-note').forEach(function (x) { x.remove(); });
      if (status) status.hidden = true;
    });
    TA.on('kb-failed', function (msg) {
      document.documentElement.setAttribute('data-kb', 'failed');
      if (status) { status.hidden = false; status.textContent = msg; }
    });
    var demo = document.getElementById('demo-date'); if (demo) demo.textContent = TA.fmtDate(TA.today());
    document.querySelectorAll('[data-meta]').forEach(function (el) { var k = el.getAttribute('data-meta'); if (TA.KB_META[k] != null) el.textContent = typeof TA.KB_META[k] === 'number' ? TA.KB_META[k].toLocaleString() : TA.KB_META[k]; });
    var nAct = TA.Actions.list.length + (TA.Process && TA.Process.list ? TA.Process.list.length : 0);
    document.querySelectorAll('[data-meta="actions"]').forEach(function (el) { el.textContent = nAct.toLocaleString(); });
    var hosts = document.getElementById('host-list');
    if (hosts && TA.KB_META.hostList) hosts.innerHTML = TA.KB_META.hostList.map(function (h) { return '<li><a href="https://' + TA.esc(h[0]) + '/" target="_blank" rel="noopener noreferrer">' + TA.esc(h[0]) + '</a><span>' + h[1] + '</span></li>'; }).join('');
    document.documentElement.setAttribute('data-ready', '1');
  }
  TA.boot = boot;
  if (!window.TA_MANUAL_BOOT) { if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot); else boot(); }
})();



